-- Associate proposed job-description drafts with the actual application role of linked employees.
-- employees.position remains the HR job title; roles.code is contextual evidence about system workflow access.
-- Existing title-only catalogue entries are retained as fallbacks; no employee or existing description is deleted.
ALTER TABLE hr_job_description_templates
    ADD COLUMN system_role_code VARCHAR(80) NOT NULL DEFAULT '' AFTER position_title,
    DROP INDEX uq_hr_job_description_position,
    ADD UNIQUE KEY uq_hr_job_description_position_role (position_title, system_role_code),
    ADD KEY idx_hr_job_description_role (system_role_code);

INSERT INTO hr_job_description_templates
    (position_title, system_role_code, role_purpose, responsibilities, description_status, is_active, created_at, updated_at)
SELECT DISTINCT
    TRIM(e.position),
    r.code,
    CASE r.code
        WHEN 'general_manager' THEN 'مسودة مستندة إلى مسارات النظام: الإشراف الإداري ومراجعة المعاملات المعروضة على المدير العام واتخاذ قرارات الاعتماد التنظيمي ضمن الصلاحيات الممنوحة.'
        WHEN 'vice_general_manager' THEN 'مسودة مستندة إلى مسارات النظام: متابعة المهام الإدارية المفوضة وإدارة إسناد المشرفين على الكفلاء وإعادة الإسناد ضمن الصلاحيات المقررة.'
        WHEN 'financial_manager' THEN 'مسودة مستندة إلى مسارات النظام: مراجعة واعتماد الإجراءات المالية المخولة، ومتابعة الخزينة والتسويات والإقفال المالي.'
        WHEN 'accountant' THEN 'مسودة مستندة إلى مسارات النظام: تنفيذ المعالجة المحاسبية المصرح بها ومراجعة المستندات والأدلة وإعداد المطابقات والتقارير.'
        WHEN 'accountant_staff' THEN 'مسودة مستندة إلى مسارات النظام: معالجة الأعمال المحاسبية المسندة ضمن الصلاحيات وتوثيق المستندات والأدلة ورفع قرارات المدير المالي إليه.'
        WHEN 'supervisor' THEN 'مسودة مستندة إلى مسارات النظام: تنفيذ أعمال الكفلاء والكفالات ضمن النطاق المسند وتقديم الطلبات التشغيلية المدعومة بالأدلة.'
        WHEN 'nanny' THEN 'مسودة مستندة إلى مسارات النظام: متابعة الأسر والأطفال المسندين وتحديث البيانات التشغيلية المسموح بها واستكمال النماذج والتحققات المطلوبة.'
        WHEN 'administration' THEN 'مسودة مستندة إلى مسارات النظام: معالجة طلبات الكفلاء ومتابعة حالات الاسترجاع والتنسيق التشغيلي وفق الصلاحيات؛ وتظل إعادة الإسناد للجهة المخولة.'
        WHEN 'staff' THEN 'مسودة مستندة إلى مسارات النظام: إنجاز الطلبات التشغيلية المعروضة في لوحة الموظفين ضمن النطاق والصلاحيات الممنوحة.'
        WHEN 'social_media' THEN 'مسودة مستندة إلى مسارات النظام: إنجاز مهام التواصل والمهام التشغيلية المصرح بها من لوحة الموظفين/الإعلام، واستخدام المواد المعتمدة فقط.'
        WHEN 'projects_manager' THEN 'مسودة مستندة إلى مسارات النظام: إعداد المشروعات وتقديمها ومتابعة تنفيذها وإغلاقها إدارياً وتنسيق الإحالة للإقفال المالي.'
        WHEN 'project_supervisor' THEN 'مسودة مستندة إلى مسارات النظام: تنفيذ أنشطة المشروع المسند وتحديث البيانات التشغيلية غير المالية وتوثيق المصروفات والأدلة المسموح بها.'
        WHEN 'hr_manager' THEN 'مسودة مستندة إلى مسارات النظام: إدارة سجلات الموظفين وحالات التوظيف والعقود والحضور والإجازات والرواتب وضوابط الموارد البشرية.'
        WHEN 'hr_staff' THEN 'مسودة مستندة إلى مسارات النظام: تنفيذ معاملات الموارد البشرية اليومية في السجلات والحضور والإجازات والرواتب وفق الصلاحيات والإجراءات المعتمدة.'
        WHEN 'admin' THEN 'مسودة مستندة إلى مسارات النظام: إدارة حسابات المستخدمين والصلاحيات والإعدادات التقنية وأعمال الصيانة المخولة؛ ولا تمنح الصلاحيات التقنية اعتماداً تجارياً أو مالياً تلقائياً.'
        WHEN 'sudo' THEN 'مسودة مستندة إلى مسارات النظام: تنفيذ مهام الإدارة التقنية العليا والصيانة المخولة؛ ولا تمنح الصلاحيات التقنية اعتماداً تجارياً أو مالياً تلقائياً.'
        ELSE 'مسودة مستندة إلى دور النظام الحالي. يجب على الموارد البشرية والمشرف المباشر مطابقة هذه المهام مع العمل الفعلي قبل الاعتماد.'
    END,
    CASE r.code
        WHEN 'general_manager' THEN '• مراجعة معاملات الاعتماد التنظيمي التي يوجهها النظام إلى المدير العام واتخاذ القرار ضمن الصلاحية.\n• مراجعة المشروعات في مرحلة الاعتماد الإداري بعد المراجعة المالية المطلوبة.\n• متابعة القرارات والنتائج المسجلة في مسارات العمل.\n• ترك الترحيل المحاسبي والتسويات والإقفال المالي للجهة المالية المخولة.'
        WHEN 'vice_general_manager' THEN '• إسناد المشرفين إلى الكفلاء وإعادة الإسناد عبر المسار المخول.\n• متابعة الأعمال الإدارية المفوضة والتنسيق بين الوحدات.\n• توثيق التغييرات ونتائج الإسناد حسب وظائف النظام.\n• عدم تنفيذ الاعتمادات المالية أو المحاسبية ما لم توجد صلاحية مستقلة موثقة.'
        WHEN 'financial_manager' THEN '• مراجعة الطلبات المالية والمستندات والأدلة قبل الاعتماد أو الترحيل ضمن الصلاحيات.\n• متابعة حسابات الخزينة والمطابقات والتسويات والتقارير المالية.\n• تنفيذ إجراءات الإقفال المالي للمشروعات بعد الإغلاق الإداري ومراجعة الرصيد وإثبات التسوية.\n• تنفيذ تسوية أموال Fina وفق مسارها وحساباتها المخصصة.\n• مراجعة معاملات السلف والاسترداد المالي وفق الإجراءات المعتمدة.'
        WHEN 'accountant' THEN '• مراجعة المعاملات في قائمة العمل المحاسبية المسندة والتحقق من المصدر والمبلغ والمستندات.\n• تنفيذ القيود أو المعالجة المحاسبية المصرح بها وتوثيق مرجع القيد والأدلة.\n• إجراء المطابقات وتتبع الأرصدة من القيود المرحلة وإعداد التقارير المسموح بها.\n• إحالة قرارات المدير المالي والتسويات المقيدة له وعدم تجاوز صلاحيات الترحيل.'
        WHEN 'accountant_staff' THEN '• معالجة المعاملات المحاسبية المسندة والتحقق من المستندات والأدلة.\n• دعم تسجيل المعاملات والمطابقات والتقارير وفق الصلاحيات.\n• توثيق المراجع والنتائج ورفع الاستثناءات إلى المحاسب أو المدير المالي.\n• عدم تنفيذ الإجراءات المحجوزة للمدير المالي.'
        WHEN 'supervisor' THEN '• العمل على سجلات الكفلاء والكفالات ضمن النطاق المحدد للمشرف.\n• تنفيذ التحديثات التشغيلية المسموح بها وتوثيق نتائج المتابعة.\n• تقديم طلبات الدفع أو المعاملات التشغيلية وإرفاق المستندات المطلوبة.\n• متابعة نتيجة الطلب وإحالة الاعتماد والترحيل المالي إلى المحاسبة/المدير المالي.'
        WHEN 'nanny' THEN '• مراجعة الأسر والأطفال والنماذج المسندة إلى الحساب.\n• تحديث المعلومات التشغيلية والتحققات المسموح بها.\n• استكمال النماذج والبيانات المطلوبة وفق الإجراءات.\n• حماية سرية بيانات الأسر والأطفال وإحالة الحالات التي تتجاوز الصلاحية.'
        WHEN 'administration' THEN '• مراجعة طلبات الكفلاء الواردة في لوحة الإدارة واستكمال إجراءاتها.\n• متابعة حالات الكفلاء المتوقفين والحالات المؤهلة للاسترجاع وتسجيل نتيجة المتابعة.\n• متابعة الأسر غير المغطاة والإجراءات التشغيلية المتاحة.\n• تنفيذ الإجراءات المصرح بها فقط؛ وإحالة تغيير الإسناد إلى الجهة المخولة.'
        WHEN 'staff' THEN '• مراجعة الطلبات والمهام التشغيلية الظاهرة في لوحة الموظفين.\n• استكمال نماذج الأيتام/طلبات الكفلاء المعروضة للحساب ضمن الصلاحية.\n• حفظ التحديثات والنتائج في مسار العمل المناسب.\n• تصعيد الاعتمادات أو التغييرات التي تتطلب دوراً آخر.'
        WHEN 'social_media' THEN '• مراجعة الطلبات المصرح بها في لوحة الموظفين/الإعلام.\n• تنفيذ مهام التواصل أو المهام التشغيلية المسندة وتوثيق النتيجة.\n• استخدام المحتوى الإعلامي المعتمد وحماية بيانات المستفيدين وعدم نشرها دون الإذن اللازم.\n• عدم استخدام إجراءات الإدارة الحصرية مثل Winback ما لم تُمنح صلاحية مستقلة.'
        WHEN 'projects_manager' THEN '• إعداد بيانات المشروع وميزانيته المقترحة وإرساله عبر مسار الاعتماد.\n• متابعة تنفيذ المشروع والتنسيق مع مشرف المشروع ومراقبة الأدلة والمصروفات التشغيلية.\n• إتمام الإغلاق الإداري مع تسجيل السبب والأدلة المطلوبة.\n• إحالة التسوية والإقفال المالي إلى المدير المالي وعدم إغلاق الرصيد مالياً بنفسه.'
        WHEN 'project_supervisor' THEN '• فتح المشروعات المسندة والتحقق من نطاق التنفيذ المعتمد.\n• تحديث البيانات التشغيلية غير المالية المسموح بها.\n• تسجيل مصروفات التنفيذ وإرفاق أدلتها وفق المسار المتاح.\n• رفع المخاطر والعوائق إلى مدير المشروع، وإحالة المطابقة والإقفال المالي إلى المدير المالي.'
        WHEN 'hr_manager' THEN '• صيانة بيانات الموظفين وربط حساب المستخدم بملف الموظف ومراجعة حالة التوظيف.\n• إدارة بيانات العقود والأوصاف الوظيفية وسجلات الرواتب التاريخية.\n• متابعة الحضور والإجازات وإعداد ومراجعة الرواتب وفق السياسات السارية.\n• تطبيق ضوابط الموارد البشرية والتنسيق مع المالية دون تجاوز صلاحياتها المحاسبية.\n• مراجعة معاملات الموارد البشرية الأخرى المتاحة للحساب ضمن الصلاحيات.'
        WHEN 'hr_staff' THEN '• تحديث سجلات الموظفين وبيانات التوظيف وفق التفويض.\n• معالجة سجلات الحضور وطلبات الإجازات ومتابعة نتائجها.\n• إعداد بيانات الرواتب ومراجعة المكونات قبل المعالجة وفق الصلاحيات.\n• حفظ المستندات والسرية وإحالة القرارات المحجوزة لمدير الموارد البشرية أو المالية.'
        WHEN 'admin' THEN '• إدارة حسابات المستخدمين والأدوار والصلاحيات ضمن التفويض.\n• دعم الإعدادات التقنية واستمرارية النظام وسلامة البيانات.\n• متابعة المشكلات التقنية وتوثيق التغييرات المصرح بها.\n• عدم افتراض أن دور الإدارة التقنية يمنح اعتماداً مالياً أو تشغيلياً محجوزاً لدور آخر.'
        WHEN 'sudo' THEN '• تنفيذ أعمال الإدارة التقنية العليا والصيانة المخولة.\n• دعم استمرارية النظام وسلامة البيانات وتوثيق التغييرات.\n• الالتزام بمبدأ أقل صلاحية وعدم استخدام الوصول التقني لتجاوز مسارات العمل أو الاعتماد المالي.'
        ELSE '• مراجعة المهام المتاحة فعلياً للحساب وتوثيق العمل المنجز.\n• الالتزام بنطاق السجلات والصلاحيات المعتمدة.\n• تصعيد المهام التي تتطلب دوراً آخر.\n• يجب على HR والمشرف المباشر تخصيص البنود وفق العمل الفعلي قبل الاعتماد.'
    END,
    'needs_review',
    1,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM employees e
JOIN users u ON u.id = e.user_id
JOIN roles r ON r.id = u.role_id
WHERE e.position IS NOT NULL
  AND TRIM(e.position) <> ''
  AND TRIM(e.position) <> 'HR Test'
  AND NOT EXISTS (
      SELECT 1
      FROM hr_job_description_templates j
      WHERE j.position_title = TRIM(e.position)
        AND j.system_role_code = r.code
  );
